query searchDepartmentsQuery(
  $query: String!
) {
  searchDepartments(query: $query) {
    code
    description
  }
}

a8292ba9197ff32a9684d5563ce0fa0a:
query searchCoursesQuery(
  $query: String!
) {
  searchCourses(query: $query) {
    subject
    number
    suffix
    title
    hours
    last_updated
  }
}

be7cf0661b551a6270f2d61d455235e6:
query searchProgramsQuery(
  $query: String!
) {
  searchPrograms(query: $query) {
    code
    description
    is_major
    is_minor
    has_concentration
    is_discontinued
    is_aacsb
    department_code
    department {
      description
    }
  }
}

c9c907d59fca0f380789ef1834d14d81:
query studentLookupQuery(
  $filters: StudentLookupInput!
  $offset: Int!
  $limit: Int!
) {
  lookupStudents(filters: $filters, offset: $offset, limit: $limit) {
    students {
      mnumber
      first_name
      last_name
      email
    }
    totalCount
  }
}
